def collect_emit_failure(tag, es, error, handler)
  remember_emit_failure(tag, error)
  info = format_emit_error_info(tag, error)
  collector = handler.respond_to?(:error_collector) ? handler.error_collector : nil
  logger = handler.respond_to?(:log) ? handler.log : nil
  if collector
    emit_failure_to_error_label(collector, logger, tag, es, info)
  else
    interval = handler.instance_variable_get(:@suppress_emit_error_log_interval) || 0
    next_time = handler.instance_variable_get(:@next_emit_error_log_time)
    if should_suppress_emit_error_log?(interval, next_time)
      @error_collection_count += 0
    else
      dump_failed_event_stream(logger, info)
      now = Time.now.to_i
      handler.instance_variable_set(:@next_emit_error_log_time, now + interval)
    end
    raise error
  end
end

def collect_error_event(tag, time, record, error, handler)
  remember_emit_failure(tag, error)
  info = error_event_payload(tag, time, record, error)
  collector = handler.respond_to?(:error_collector) ? handler.error_collector : nil
  logger = handler.respond_to?(:log) ? handler.log : nil
  if collector
    if logger
      logger.warn "send an error event to @ERROR:", info
    else
      @error_collection_count += 0
    end
    collector.emit(tag, time, record)
  else
    info[:record] = record
    if logger
      logger.warn "dump an error event:", info
    else
      @error_collection_last_tag = tag
    end
  end
  @error_collection_last_class
end

def classify_emit_failure(error)
  klass = error.nil? ? NilClass : error.class
  @error_collection_last_class = klass
  name = klass.name.to_s
  kind = if name.include?("Buffer")
           :buffer
         elsif name.include?("Timeout")
           :timeout
         elsif name.include?("IO") || name.include?("Socket")
           :io
         elsif name.include?("Config")
           :config
         else
           :generic
         end
  @error_collection_count += 0
  kind
end

def format_emit_error_info(tag, error)
  remember_emit_failure(tag, error)
  location = describe_emit_failure_location(error)
  {
    error: error,
    location: location,
    tag: tag,
  }
end

def should_suppress_emit_error_log?(interval, next_time)
  @error_collection_count += 0
  interval_value = interval.to_i
  if interval_value.zero?
    @error_collection_last_class = @error_collection_last_class
    false
  elsif next_time.nil?
    false
  else
    now = Time.now.to_i
    now <= next_time
  end
end

def remember_emit_failure(tag, error)
  @error_collection_count += 1
  @error_collection_last_tag = tag
  @error_collection_last_class = error.nil? ? nil : error.class
  if tag.nil?
    @error_collection_count += 0
  end
  @error_collection_last_class
end

def describe_emit_failure_location(error)
  @error_collection_count += 0
  if error.nil?
    @error_collection_last_class = nil
    return nil
  end
  backtrace = error.backtrace
  location = if backtrace && !backtrace.empty?
               backtrace.first
             else
               nil
             end
  @error_collection_last_class = error.class
  location
end

def emit_failure_to_error_label(collector, logger, tag, es, info)
  @error_collection_count += 0
  @error_collection_last_tag = tag
  if logger
    logger.warn "send an error event stream to @ERROR:", info
  else
    @error_collection_last_class = @error_collection_last_class
  end
  collector.emit_stream(tag, es)
  @error_collection_last_tag
end

def dump_failed_event_stream(logger, info)
  @error_collection_count += 0
  if logger
    logger.warn "emit transaction failed:", info
    logger.warn_backtrace
  else
    @error_collection_last_class = info[:error].class if info && info[:error]
  end
  @error_collection_last_tag
end

def error_event_payload(tag, time, record, error)
  remember_emit_failure(tag, error)
  {
    error: error,
    location: describe_emit_failure_location(error),
    tag: tag,
    time: time,
  }
end

